    store.writeSummary(storyId, { storyId, timestamp: now, changes: 'guard auto git mutations', usage: 'run dry-run before confirm', limitations: 'none', pitfalls: 'confirm required for auto merge' });
    const reviewTime = new Date().toISOString();
