    store.writeReview(storyId, { reviews: [{ timestamp: reviewTime, issueCount: 0, blockerCount: 0, issues: [], _hash: hash }] });
    store.writeImplementationReview(storyId, { storyId, verdict: 'pass', findings: [], summary: 'clean implementation review', createdAt: now, updatedAt: now });
  }
  const handlers = createWorktreeHandlers({ store, root: wtPath, scanRoot: join(wtPath, 'packages', 'main') });
  return { dir, wtPath, handlers };
}
let blocked = false;
let finishBlocked = false;
let mergeBlocked = false;
let dirs = [];
try {
  const doneRepo = setupRepo('B-done', 'TEST');
  dirs.push(doneRepo.dir);
  try { run(doneRepo.wtPath, doneRepo.wtPath, ['story_advance', JSON.stringify({ storyId: 'B-done', phase: 'DONE' })]); } catch (error) { const text = String(error.stdout || '') + String(error.stderr || ''); blocked = text.includes('默认已阻止') && text.includes('DONE auto-git plan'); }
  const finishRepo = setupRepo('B-finish', 'DEV');
  dirs.push(finishRepo.dir);
  process.chdir(finishRepo.wtPath);
  try { finishRepo.handlers.dev_finish({ storyId: 'B-finish' }); } catch (error) { finishBlocked = String(error.message || error).includes('默认已阻止'); }
  const mergeRepo = setupRepo('B-merge', 'DONE');
  dirs.push(mergeRepo.dir);
  process.chdir(mergeRepo.wtPath);
  try { mergeRepo.handlers.dev_merge({ storyId: 'B-merge' }); } catch (error) { mergeBlocked = String(error.message || error).includes('默认已阻止'); }
  return { blocked, finishBlocked, mergeBlocked };
} finally {
  try { process.chdir(origCwd); } catch {}
  for (const dir of dirs) rmSync(dir, { recursive: true, force: true });
}

